solutionCode:
#include <stdio.h>

void trocarOsValores(void) {
    int cofre = 7;
    int gaveta = 2;

    int guardado = cofre;
    cofre = gaveta;
    gaveta = guardado;

    printf("cofre: %d\n", cofre);
    printf("gaveta: %d\n", gaveta);
}
